public class DutchNationalFlag {
    /**
     * Partitions array into three regions:
     * [< pivot | == pivot | > pivot]
     * Runs in O(n) time with O(1) extra space.
     */
    public static void partition(int[] arr, int pivot) {
        int low = 0, mid = 0, high = arr.length - 1;

        while (mid <= high) {
            if (arr[mid] < pivot) {
                swap(arr, low++, mid++);
            } else if (arr[mid] == pivot) {
                mid++;
            } else {
                swap(arr, mid, high--);
            }
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

/**
 * Alternative implementation using Comparable for generic types.
 * Partitions array in-place into [< pivot, == pivot, > pivot].
 */
public static <T extends Comparable<T>> void dutchNationalFlag(T[] arr, T pivot) {
    int low = 0, mid = 0, high = arr.length - 1;

    while (mid <= high) {
        int cmp = arr[mid].compareTo(pivot);
        if (cmp < 0) {
            T temp = arr[low];
            arr[low] = arr[mid];
            arr[mid] = temp;
            low++;
            mid++;
        } else if (cmp == 0) {
            mid++;
        } else {
            T temp = arr[mid];
            arr[mid] = arr[high];
            arr[high] = temp;
            high--;
        }
    }
}

public class DynamicArray<T> {
    private Object[] data;
    private int size;
    private static final int DEFAULT_CAPACITY = 10;
    private static final double GROWTH_FACTOR = 1.5;

    public DynamicArray() {
        this.data = new Object[DEFAULT_CAPACITY];
        this.size = 0;
    }

    @SuppressWarnings("unchecked")
    public T get(int index) {
        if (index < 0 || index >= size) throw new IndexOutOfBoundsException();
        return (T) data[index];
    }

    public void add(T element) {
        if (size == data.length) {
            resize((int) (data.length * GROWTH_FACTOR) + 1);
        }
        data[size++] = element;
    }

    private void resize(int newCapacity) {
        Object[] newData = new Object[newCapacity];
        System.arraycopy(data, 0, newData, 0, size);
        data = newData;
    }

    public int size() { return size; }
}

